def _help_bkfrag(doc, lang):
    if 'id="blinki"' in doc or not _HELP_BKFRAG.get(lang):
        return doc
    i = doc.find('<section id="tips"')
    return doc[:i] + _HELP_BKFRAG[lang] + doc[i:] if i >= 0 else doc


_hp_en_bkfrag = HELP_PAGE.find('<div lang="en">') if isinstance(HELP_PAGE, str) else -1
if _hp_en_bkfrag > 0:
    HELP_PAGE = _help_bkfrag(HELP_PAGE[:_hp_en_bkfrag], "de") + _help_bkfrag(HELP_PAGE[_hp_en_bkfrag:], "en")
for _L in ("fr", "it", "rm"):
    if isinstance(HELP_X, dict) and HELP_X.get(_L):
        HELP_X[_L] = _help_bkfrag(HELP_X[_L], _L)


# ---- self-test (no network, no process) -------------------------------------------------------------------------------------------
def bkfrag_selftest():
    m = BLINKI_MODELS[BLINKI_MODEL_DEFAULT]
    assert blinki_pinned(BLINKI_MODEL_DEFAULT) and m["size"] > 9e8 and "Apache-2.0" in m["licence"], "the model: pinned revision, size, checksum, licence"
    assert re.fullmatch(r"[0-9a-f]{40}", BLINKI_LLAMA["commit"]) and blinki_model_url(BLINKI_MODEL_DEFAULT).startswith("https://huggingface.co/Qwen/")
    assert blinki_words("Wie laut ist die Sirene?") == ["laut", "siren"], blinki_words("Wie laut ist die Sirene?")
    hits = blinki_search("Wie laut ist die Sirene?", "de", 3)
    assert hits and all(h["href"].startswith("/") for h in hits), "the search finds something with an address in MoveEye"
    assert blinki_search("", "de") == [] and blinki_pieces("Eins. Zwei **fett**! " + "x" * 400)[0] == "Eins. Zwei fett!" and all(len(x) <= 180 for x in blinki_pieces("y " * 400)), "pieces for the voice"
    assert not blinki_mode_ok("fehler", "family") and blinki_mode_ok("frag", "view") and not blinki_mode_ok("frag", "kid") and blinki_mode_ok("fehler", "admin")
    assert role_allows("view", "/api/ki/ask", "POST", {"mode": "frag"}) and not role_allows("family", "/api/ki/ask", "POST", {"mode": "fehler"})
    assert not role_allows("family", "/api/ki/model", "POST", {"action": "load"}) and not role_allows("family", "/api/ki/set", "POST", {})
    assert not role_allows("view", "/api/ki/say", "POST", {"where": "pi"}) and role_allows("family", "/api/ki/say", "POST", {"where": "pi"})
    assert role_allows("view", "/blinki", "GET", {}) and role_allows("view", "/api/ki/job/0123456789ab", "GET", {})
    assert blinki_fix("X", False)[0] is False and blinki_fix("X", "true")[0] is False, "a fix only with the OK (True)"
    assert all(BLINKI_FIX_DENY.search(a) for a in ("protect_off", "disarm", "schutz_aus", "alarm_off")), "never the protection off"
    assert blinki_piece({"choices": [{"delta": {"content": "Hi"}}]}) == "Hi" and blinki_piece({"type": "content_block_delta", "delta": {"text": "Yo"}}) == "Yo"
    assert all(DE.get(k) and all(TRX[L].get(k) for L in ("fr", "it", "rm")) for k in BKFRAG_TX), "texts in 5 languages"
    assert blinki_mode_ok("plaudern", "view") and not blinki_mode_ok("plaudern", "kid") and "plaudern" in BLINKI_EXTRA_MODES, "💬 Plaudern: rights"
    for k_ in range(6):
        blinki_chat_add("selftest", "q%d" % k_, "a")
    assert [x[0] for x in blinki_chat_turns("selftest")] == ["q2", "q3", "q4", "q5"] and blinki_chat_forget("selftest") == 1 and not blinki_chat_turns("selftest"), "chat history"
    assert all(x in BLINKI_CHAT_RULES for x in ("at most 8 sentences", "children from 10", "current events", "protection", "Health, law and money")), "chat rules"
    return "pins, search, rights, fix only with OK, stream pieces, texts, chat"


SELFTEST_EXTRA.append(("Blinki fragen: pins, search, rights (639zzzzk)", bkfrag_selftest))
